-- ============================================================
-- 一次性迁移：erp_admin_permission 三级目录重组（域 > 子域 > 操作）
--
-- 目的：业务域菜单下插入中间子域目录(type=1)，原叶子(type=3 API)重挂其下，
--       形成 3 级权限树，供双端角色权限弹框树形勾选。
-- 关键不变量：只 INSERT 目录行 + UPDATE 叶子 parent_id；叶子 id 全部不变，
--       erp_admin_role_permission 既有关联全部天然有效。
-- 执行前置核对（本库实测）：erp_admin_permission=300 行；
--       erp_admin_role_permission=300 行（super_admin 全授）。
-- 执行后预期：permission=359 行（300+59 目录）；role_permission=359 行。
-- 仅需执行一次；重复执行会因目录主键冲突失败（无破坏，可直接忽略报错）。
--
-- 逆操作（回滚，按序执行）：
--   1) DELETE FROM erp_admin_role_permission WHERE permission_id IN (
--        <下方 59 个目录 id 清单> );
--   2) UPDATE erp_admin_permission SET parent_id=<原域菜单id> WHERE id IN (
--        <叶子 id 清单> );   -- 见各目录 UPDATE 语句注释中的原 parent 值
--   3) DELETE FROM erp_admin_permission WHERE type=1 AND id IN (<目录 id 清单>);
-- ============================================================

START TRANSACTION;

