-- 三、新目录授予超级管理员（与 install.sql 全量补授同款幂等写法）
INSERT INTO `erp_admin_role_permission` (`role_id`, `permission_id`)
SELECT 10000000000000001, `id` FROM `erp_admin_permission`
WHERE `id` IN (31000000000000010, 31000000000000020, 31000000000000030, 31000000000000040, 31000000000000050, 31000000000000060, 31000000000000070, 31000000000000080, 31000000000000090, 31000000000000100, 31000000000000110, 31000000000000130, 31000000000000140, 31000000000000150, 31000000000000160, 31000000000000195, 31000000000000196, 31000000000000197, 31000000000000200, 31000000000000219, 31000000000000220, 31000000000000230, 31000000000000250, 31000000000000270, 31000000000000750, 31000000000000280, 31000000000000290, 31000000000000300, 31000000000000310, 31000000000000340, 31000000000000350, 31000000000000360, 31000000000000370, 31000000000000400, 31000000000000410, 31000000000000420, 31000000000000430, 31000000000000440, 31000000000000450, 31000000000000460, 31000000000000470, 31000000000000500, 31000000000000510, 31000000000000520, 31000000000000530, 31000000000000540, 31000000000000550, 31000000000000700, 31000000000000710, 31000000000000724, 31000000000000725, 31000000000000726, 31000000000000730, 31000000000000645, 31000000000000646, 31000000000000647, 31000000000000648, 31000000000000649, 31000000000000650)
AND `id` NOT IN (SELECT `permission_id` FROM `erp_admin_role_permission` WHERE `role_id` = 10000000000000001);

-- 四、终态自检（期望：359 / 359）
SELECT COUNT(*) AS permission_total FROM `erp_admin_permission`;
SELECT COUNT(*) AS super_admin_perm_count FROM `erp_admin_role_permission` WHERE `role_id`=10000000000000001;

COMMIT;
